input.content:
import { cn } from '@/lib/utils'
import type { Database } from '@/lib/supabase/types'

type BookingStatus =
  Database['public']['Tables']['bookings']['Row']['status']

const STATUS_LABELS: Record<BookingStatus, string> = {
  pending: 'Pending',
  confirmed: 'Confirmed',
  in_progress: 'In Progress',
  completed: 'Completed',
  cancelled: 'Cancelled',
  no_show: 'No Show',
}

const STATUS_CLASSES: Record<BookingStatus, string> = {
  pending: 'badge-pending',
  confirmed: 'badge-confirmed',
  in_progress: 'badge-in-progress',
  completed: 'badge-completed',
  cancelled: 'badge-cancelled',
  no_show: 'badge-no-show',
}

interface AppointmentStatusBadgeProps {
  status: BookingStatus
  className?: string
  showDot?: boolean
}

export function AppointmentStatusBadge({
  status,
  className,
  showDot = true,
}: AppointmentStatusBadgeProps) {
  return (
    <span
      className={cn(
        'inline-flex items-center gap-1.5 rounded-full px-2 py-0.5 text-xs font-medium',
        STATUS_CLASSES[status],
        className
      )}
    >
      {showDot && (
        <span
          className="h-1.5 w-1.5 rounded-full bg-current"
          aria-hidden="true"
        />
      )}
      {STATUS_LABELS[status]}
    </span>
  )
}

'use client'

import { cn } from '@/lib/utils'
import { Check } from 'lucide-react'

interface Step {
  label: string
}

interface BookingStepIndicatorProps {
  steps: Step[]
  currentStep: number
  className?: string
}

export function BookingStepIndicator({
  steps,
  currentStep,
  className,
}: BookingStepIndicatorProps) {
  return (
    <nav aria-label="Booking progress" className={cn('flex items-center gap-0', className)}>
      {steps.map((step, index) => {
        const isDone = index < currentStep
        const isActive = index === currentStep
        const isFuture = index > currentStep

        return (
          <div key={step.label} className="flex items-center">
            <div className="flex flex-col items-center gap-1">
              <div
                aria-current={isActive ? 'step' : undefined}
                className={cn(
                  'flex h-7 w-7 items-center justify-center rounded-full text-xs font-semibold transition-all duration-200',
                  isDone && 'timeline-step-done bg-[var(--color-timeline-dot-done)] text-white',
                  isActive &&
                    'timeline-step-active bg-[var(--color-booking-step-active)] text-white shadow-[0_0_10px_var(--color-booking-step-active)]',
                  isFuture &&
                    'timeline-step-future bg-transparent border border-[var(--color-booking-step-future)] text-muted-foreground'
                )}
              >
                {isDone ? <Check className="h-3.5 w-3.5" /> : index + 1}
              </div>
              <span
                className={cn(
                  'text-[10px] font-medium whitespace-nowrap',
                  isActive && 'text-foreground',
                  isDone && 'text-[var(--color-timeline-dot-done)]',
                  isFuture && 'text-muted-foreground'
                )}
              >
                {step.label}
              </span>
            </div>
            {index < steps.length - 1 && (
              <div
                className={cn(
                  'h-px w-12 mx-1 mb-5 transition-colors duration-200',
                  index < currentStep
                    ? 'bg-[var(--color-timeline-dot-done)]'
                    : 'bg-[var(--color-timeline-line)]'
                )}
              />
            )}
          </div>
        )
      })}
    </nav>
  )
}

'use client'

import { cn } from '@/lib/utils'
import { Check, Circle, Clock } from 'lucide-react'
import type { Database } from '@/lib/supabase/types'

type BookingStatus =
  Database['public']['Tables']['bookings']['Row']['status']

const TIMELINE_STEPS: { status: BookingStatus; label: string }[] = [
  { status: 'pending', label: 'Pending' },
  { status: 'confirmed', label: 'Confirmed' },
  { status: 'in_progress', label: 'In Progress' },
  { status: 'completed', label: 'Completed' },
]

const STATUS_ORDER: Record<BookingStatus, number> = {
  pending: 0,
  confirmed: 1,
  in_progress: 2,
  completed: 3,
  cancelled: -1,
  no_show: -1,
}

interface AppointmentTimelineProps {
  status: BookingStatus
  createdAt: string
  scheduledAt: string
  className?: string
}

export function AppointmentTimeline({
  status,
  createdAt,
  scheduledAt,
  className,
}: AppointmentTimelineProps) {
  const currentOrder = STATUS_ORDER[status]
  const isTerminal = status === 'cancelled' || status === 'no_show'

  return (
    <div className={cn('space-y-1', className)}>
      {isTerminal && (
        <div className="mb-3 flex items-center gap-2 rounded-md bg-destructive/10 px-3 py-2 text-sm text-destructive">
          <Circle className="h-4 w-4 shrink-0" />
          <span className="font-medium capitalize">
            {status === 'cancelled' ? 'Cancelled' : 'No Show'}
          </span>
        </div>
      )}

      <div className="flex gap-3">
        {/* Vertical line */}
        <div className="flex flex-col items-center">
          <div className="flex flex-col gap-0">
            {TIMELINE_STEPS.map((step, index) => {
              const stepOrder = STATUS_ORDER[step.status]
              const isDone = !isTerminal && currentOrder > stepOrder
              const isActive = !isTerminal && currentOrder === stepOrder
              const isFuture = isTerminal || currentOrder < stepOrder

              return (
                <div key={step.status} className="flex flex-col items-center">
                  <div
                    className={cn(
                      'flex h-7 w-7 items-center justify-center rounded-full border-2 transition-all',
                      isDone &&
                        'border-transparent bg-[var(--color-timeline-dot-done)] text-white',
                      isActive &&
                        'border-transparent bg-[var(--color-timeline-dot-active)] text-white shadow-[0_0_10px_var(--color-timeline-dot-active)]',
                      isFuture && 'border-[var(--color-timeline-line)] bg-transparent'
                    )}
                  >
                    {isDone && <Check className="h-3.5 w-3.5" />}
                    {isActive && <Clock className="h-3.5 w-3.5" />}
                    {isFuture && (
                      <span className="h-2 w-2 rounded-full bg-[var(--color-timeline-line)]" />
                    )}
                  </div>
                  {index < TIMELINE_STEPS.length - 1 && (
                    <div
                      className={cn(
                        'w-0.5 flex-1 min-h-[1.5rem]',
                        isDone
                          ? 'bg-[var(--color-timeline-dot-done)]'
                          : 'bg-[var(--color-timeline-line)]'
                      )}
                    />
                  )}
                </div>
              )
            })}
          </div>
        </div>

        {/* Step labels */}
        <div className="flex flex-col justify-between py-0.5">
          {TIMELINE_STEPS.map((step) => {
            const stepOrder = STATUS_ORDER[step.status]
            const isDone = !isTerminal && currentOrder > stepOrder
            const isActive = !isTerminal && currentOrder === stepOrder

            const timestamp =
              step.status === 'pending'
                ? new Date(createdAt).toLocaleDateString('en-US', {
                    month: 'short',
                    day: 'numeric',
                    hour: '2-digit',
                    minute: '2-digit',
                  })
                : step.status === 'confirmed' || step.status === 'in_progress'
                  ? isActive || isDone
                    ? new Date(scheduledAt).toLocaleDateString('en-US', {
                        month: 'short',
                        day: 'numeric',
                      })
                    : null
                  : null

            return (
              <div key={step.status} className="flex min-h-[1.75rem] flex-col justify-center">
                <span
                  className={cn(
                    'text-sm font-medium',
                    isActive && 'text-foreground',
                    isDone && 'text-[var(--color-timeline-dot-done)]',
                    !isActive && !isDone && 'text-muted-foreground'
                  )}
                >
                  {step.label}
                </span>
                {timestamp && (
                  <span className="text-xs tabular-nums text-muted-foreground">
                    {timestamp}
                  </span>
                )}
              </div>
            )
          })}
        </div>
      </div>
    </div>
  )
}

import { NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import { createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

const ListBookingsSchema = z.object({
  from: z.string().datetime().optional(),
  to: z.string().datetime().optional(),
  artist_id: z.string().uuid().optional(),
  status: z
    .enum(['pending', 'confirmed', 'in_progress', 'completed', 'cancelled', 'no_show'])
    .optional(),
  page: z.coerce.number().int().min(1).default(1),
  per_page: z.coerce.number().int().min(1).max(100).default(50),
  q: z.string().max(200).optional(),
})

const CreateBookingSchema = z.object({
  client_id: z.string().uuid(),
  artist_id: z.string().uuid(),
  service_id: z.string().uuid().optional(),
  location_id: z.string().uuid().optional(),
  scheduled_at: z.string().datetime(),
  duration_min: z.number().int().min(15).max(480),
  price_cents: z.number().int().min(0),
  deposit_cents: z.number().int().min(0).optional(),
  notes: z.string().max(2000).optional(),
  source: z.enum(['internal', 'waitlist']).default('internal'),
})

export async function GET(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  const { searchParams } = new URL(request.url)
  const parsed = ListBookingsSchema.safeParse(Object.fromEntries(searchParams))
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  const { from, to, artist_id, status, page, per_page, q } = parsed.data
  const offset = (page - 1) * per_page

  try {
    const supabase = await createClient()
    let query = supabase
      .from('bookings')
      .select(
        `
        id, scheduled_at, end_at, duration_min, status, price_cents, deposit_paid,
        booking_token, source, notes, created_at,
        client:clients(id, first_name, last_name, email, phone),
        artist:artists(id, display_name, avatar_url, sort_order),
        service:services(id, name, duration_min, color)
      `,
        { count: 'exact' }
      )
      .eq('studio_id', authUser.studioId)
      .order('scheduled_at', { ascending: false })
      .range(offset, offset + per_page - 1)

    if (from) query = query.gte('scheduled_at', from)
    if (to) query = query.lte('scheduled_at', to)
    if (artist_id) query = query.eq('artist_id', artist_id)
    if (status) query = query.eq('status', status)
    if (q) query = query.textSearch('fts', q, { type: 'websearch' })

    const { data, error, count } = await query

    if (error) {
      logger.error({ err: error, studioId: authUser.studioId }, 'bookings list failed')
      return NextResponse.json({ error: 'Failed to fetch bookings' }, { status: 500 })
    }

    return NextResponse.json({
      data: data ?? [],
      count: count ?? 0,
      page,
      per_page,
      total_pages: Math.ceil((count ?? 0) / per_page),
    })
  } catch (err) {
    logger.error({ err }, 'bookings GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

export async function POST(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = CreateBookingSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  const { client_id, artist_id, service_id, location_id, scheduled_at, duration_min, price_cents, deposit_cents, notes, source } = parsed.data

  try {
    const supabase = await createClient()

    const { data, error } = await supabase
      .from('bookings')
      .insert({
        studio_id: authUser.studioId,
        client_id,
        artist_id,
        service_id: service_id ?? null,
        location_id: location_id ?? null,
        scheduled_at,
        duration_min,
        price_cents,
        deposit_cents: deposit_cents ?? 0,
        notes: notes ?? null,
        source,
        status: 'pending',
      })
      .select(
        `id, scheduled_at, end_at, duration_min, status, price_cents, deposit_paid, booking_token,
         client:clients(id, first_name, last_name, email),
         artist:artists(id, display_name),
         service:services(id, name)`
      )
      .single()

    if (error) {
      if (error.code === '23P01') {
        return NextResponse.json(
          { error: 'That time slot is already booked for this artist' },
          { status: 409 }
        )
      }
      logger.error({ err: error, studioId: authUser.studioId }, 'booking create failed')
      return NextResponse.json({ error: 'Failed to create booking' }, { status: 500 })
    }

    return NextResponse.json({ data }, { status: 201 })
  } catch (err) {
    logger.error({ err }, 'bookings POST unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import { createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

const UpdateBookingSchema = z.object({
  artist_id: z.string().uuid().optional(),
  service_id: z.string().uuid().nullable().optional(),
  location_id: z.string().uuid().nullable().optional(),
  scheduled_at: z.string().datetime().optional(),
  duration_min: z.number().int().min(15).max(480).optional(),
  price_cents: z.number().int().min(0).optional(),
  deposit_cents: z.number().int().min(0).optional(),
  notes: z.string().max(2000).nullable().optional(),
  client_notes: z.string().max(2000).nullable().optional(),
})

interface Params {
  params: Promise<{ id: string }>
}

export async function GET(_request: NextRequest, { params }: Params) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  const { id } = await params
  if (!z.string().uuid().safeParse(id).success) {
    return NextResponse.json({ error: 'Invalid booking ID' }, { status: 400 })
  }

  try {
    const supabase = await createClient()
    const { data, error } = await supabase
      .from('bookings')
      .select(
        `
        *,
        client:clients(id, first_name, last_name, email, phone, total_sessions, total_spent_cents, tags, notes),
        artist:artists(id, display_name, avatar_url, sort_order),
        service:services(id, name, duration_min, base_price_cents, deposit_cents, color),
        location:locations(id, name, address, city),
        photos:booking_photos(id, kind, caption, taken_at, storage_path)
      `
      )
      .eq('id', id)
      .eq('studio_id', authUser.studioId)
      .single()

    if (error || !data) {
      return NextResponse.json({ error: 'Booking not found' }, { status: 404 })
    }

    return NextResponse.json({ data })
  } catch (err) {
    logger.error({ err, bookingId: id }, 'booking GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

export async function PATCH(request: NextRequest, { params }: Params) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  const { id } = await params
  if (!z.string().uuid().safeParse(id).success) {
    return NextResponse.json({ error: 'Invalid booking ID' }, { status: 400 })
  }

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = UpdateBookingSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  if (Object.keys(parsed.data).length === 0) {
    return NextResponse.json({ error: 'No fields to update' }, { status: 400 })
  }

  try {
    const supabase = await createClient()
    const { data, error } = await supabase
      .from('bookings')
      .update(parsed.data)
      .eq('id', id)
      .eq('studio_id', authUser.studioId)
      .select('id, scheduled_at, end_at, duration_min, status, price_cents, notes, updated_at')
      .single()

    if (error) {
      if (error.code === '23P01') {
        return NextResponse.json(
          { error: 'That time slot is already booked for this artist' },
          { status: 409 }
        )
      }
      if (error.code === 'PGRST116') {
        return NextResponse.json({ error: 'Booking not found' }, { status: 404 })
      }
      logger.error({ err: error, bookingId: id }, 'booking PATCH failed')
      return NextResponse.json({ error: 'Failed to update booking' }, { status: 500 })
    }

    return NextResponse.json({ data })
  } catch (err) {
    logger.error({ err, bookingId: id }, 'booking PATCH unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

export async function DELETE(_request: NextRequest, { params }: Params) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  const { id } = await params
  if (!z.string().uuid().safeParse(id).success) {
    return NextResponse.json({ error: 'Invalid booking ID' }, { status: 400 })
  }

  try {
    const supabase = await createClient()
    const { error } = await supabase
      .from('bookings')
      .update({ status: 'cancelled', cancelled_at: new Date().toISOString() })
      .eq('id', id)
      .eq('studio_id', authUser.studioId)

    if (error) {
      if (error.code === 'PGRST116') {
        return NextResponse.json({ error: 'Booking not found' }, { status: 404 })
      }
      logger.error({ err: error, bookingId: id }, 'booking DELETE failed')
      return NextResponse.json({ error: 'Failed to cancel booking' }, { status: 500 })
    }

    return new NextResponse(null, { status: 204 })
  } catch (err) {
    logger.error({ err, bookingId: id }, 'booking DELETE unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import { createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logAuditAction } from '@/lib/audit'
import { logger } from '@/lib/logger'
import type { Database } from '@/lib/supabase/types'

type BookingStatus = Database['public']['Tables']['bookings']['Row']['status']

// Allowed forward transitions only — spec section 6
const ALLOWED_TRANSITIONS: Record<BookingStatus, BookingStatus[]> = {
  pending: ['confirmed', 'cancelled'],
  confirmed: ['in_progress', 'cancelled', 'no_show'],
  in_progress: ['completed', 'cancelled'],
  completed: [],
  cancelled: [],
  no_show: [],
}

const StatusUpdateSchema = z.object({
  status: z.enum([
    'pending',
    'confirmed',
    'in_progress',
    'completed',
    'cancelled',
    'no_show',
  ]),
  cancellation_reason: z.string().max(500).optional(),
})

interface Params {
  params: Promise<{ id: string }>
}

export async function PATCH(request: NextRequest, { params }: Params) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  const { id } = await params
  if (!z.string().uuid().safeParse(id).success) {
    return NextResponse.json({ error: 'Invalid booking ID' }, { status: 400 })
  }

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = StatusUpdateSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  const { status: newStatus, cancellation_reason } = parsed.data

  try {
    const supabase = await createClient()

    // Fetch current booking to validate transition
    const { data: existing, error: fetchError } = await supabase
      .from('bookings')
      .select('id, status, studio_id')
      .eq('id', id)
      .eq('studio_id', authUser.studioId)
      .single()

    if (fetchError || !existing) {
      return NextResponse.json({ error: 'Booking not found' }, { status: 404 })
    }

    const allowed = ALLOWED_TRANSITIONS[existing.status]
    if (!allowed.includes(newStatus)) {
      return NextResponse.json(
        {
          error: `Cannot transition from ${existing.status} to ${newStatus}`,
          allowed_transitions: allowed,
        },
        { status: 422 }
      )
    }

    const updatePayload: Database['public']['Tables']['bookings']['Update'] = {
      status: newStatus,
    }
    if (newStatus === 'cancelled') {
      updatePayload.cancelled_at = new Date().toISOString()
      updatePayload.cancelled_by = authUser.user.id
      if (cancellation_reason) {
        updatePayload.cancellation_reason = cancellation_reason
      }
    }

    const { data, error } = await supabase
      .from('bookings')
      .update(updatePayload)
      .eq('id', id)
      .eq('studio_id', authUser.studioId)
      .select('id, status, cancelled_at, cancellation_reason, updated_at')
      .single()

    if (error) {
      logger.error({ err: error, bookingId: id, newStatus }, 'booking status update failed')
      return NextResponse.json({ error: 'Failed to update status' }, { status: 500 })
    }

    // Audit log
    await logAuditAction(
      authUser.user.id,
      `booking.status.${newStatus}`,
      { type: 'booking', id },
      { from: existing.status, to: newStatus, cancellation_reason: cancellation_reason ?? null },
      authUser.studioId
    )

    return NextResponse.json({ data })
  } catch (err) {
    logger.error({ err, bookingId: id }, 'booking status PATCH unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
