const ListArtistsSchema = z.object({
  status: z.enum(['active', 'on_leave', 'archived']).optional(),
  service_id: z.string().uuid().optional(),
})

export async function GET(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  const { searchParams } = new URL(request.url)
  const parsed = ListArtistsSchema.safeParse(Object.fromEntries(searchParams))
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  const { status, service_id } = parsed.data

  try {
    const supabase = await createClient()

    if (service_id) {
      // Fetch artists that can perform this service (via service_artists join)
      const { data, error } = await supabase
        .from('service_artists')
        .select(
          `
          artist:artists(
            id, display_name, avatar_url, specialties, status, sort_order,
            price_override_cents:service_artists(price_override_cents),
            duration_override_min:service_artists(duration_override_min)
          )
        `
        )
        .eq('service_id', service_id)

      if (error) {
        logger.error({ err: error }, 'artists by service list failed')
        return NextResponse.json({ error: 'Failed to fetch artists' }, { status: 500 })
      }

      const artists = (data ?? [])
        .map((row) => row.artist)
        .filter(Boolean)
        .filter((a) => !status || (a as { status: string }).status === status)

      return NextResponse.json({ data: artists })
    }

    let query = supabase
      .from('artists')
      .select('id, display_name, avatar_url, specialties, status, sort_order, commission_default_pct')
      .eq('studio_id', authUser.studioId)
      .order('sort_order', { ascending: true })

    if (status) query = query.eq('status', status)

    const { data, error } = await query

    if (error) {
      logger.error({ err: error, studioId: authUser.studioId }, 'artists list failed')
      return NextResponse.json({ error: 'Failed to fetch artists' }, { status: 500 })
    }

    return NextResponse.json({ data: data ?? [] })
  } catch (err) {
    logger.error({ err }, 'artists GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

