    .optional(),
  artist_id: z.string().uuid().optional(),
  page: z.coerce.number().int().min(1).default(1),
  per_page: z.coerce.number().int().min(1).max(100).default(50),
})

const CreateWaitlistSchema = z.object({
  client_id: z.string().uuid(),
  service_id: z.string().uuid().nullable().optional(),
  artist_id: z.string().uuid().nullable().optional(),
  preferred_dates: z.string().optional(), // daterange string format "[2026-05-01,2026-06-30)"
  preferred_days_of_week: z.array(z.number().int().min(0).max(6)).optional(),
  notes: z.string().max(1000).optional(),
})

export async function GET(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  const { searchParams } = new URL(request.url)
  const parsed = ListWaitlistSchema.safeParse(Object.fromEntries(searchParams))
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  const { status, artist_id, page, per_page } = parsed.data
  const offset = (page - 1) * per_page

  try {
    const supabase = await createClient()
    let query = supabase
      .from('waitlist_entries')
      .select(
        `
        id, preferred_dates, preferred_days_of_week, notes, status,
        offered_booking_id, offered_at, offered_expires_at, created_at,
        client:clients(id, first_name, last_name, email, phone),
        service:services(id, name, duration_min, color),
        artist:artists(id, display_name, avatar_url)
      `,
        { count: 'exact' }
      )
      .eq('studio_id', authUser.studioId)
      .order('created_at', { ascending: false })
      .range(offset, offset + per_page - 1)

    if (status) query = query.eq('status', status)
    if (artist_id) query = query.eq('artist_id', artist_id)

    const { data, error, count } = await query

    if (error) {
      logger.error({ err: error, studioId: authUser.studioId }, 'waitlist list failed')
      return NextResponse.json({ error: 'Failed to fetch waitlist' }, { status: 500 })
    }

    return NextResponse.json({
      data: data ?? [],
      count: count ?? 0,
      page,
      per_page,
      total_pages: Math.ceil((count ?? 0) / per_page),
    })
  } catch (err) {
    logger.error({ err }, 'waitlist GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

