    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = CreateWaitlistSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  try {
    const supabase = await createClient()
    const { data, error } = await supabase
      .from('waitlist_entries')
      .insert({
        studio_id: authUser.studioId,
        client_id: parsed.data.client_id,
        service_id: parsed.data.service_id ?? null,
        artist_id: parsed.data.artist_id ?? null,
        preferred_dates: parsed.data.preferred_dates ?? null,
        preferred_days_of_week: parsed.data.preferred_days_of_week ?? [],
