  scheduled_at: z.string().datetime(),
  client_data: z.object({
    first_name: z.string().min(1).max(100),
    last_name: z.string().max(100).optional(),
    email: z.string().email().max(254),
    phone: z.string().max(30).optional(),
  }),
})

export async function POST(request: NextRequest) {
  const ip = request.headers.get('x-forwarded-for') ?? 'anonymous'
  const { success } = await publicBookingCreateRatelimit.limit(ip)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = CreatePublicBookingSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  const { token, studio_slug, service_id, artist_id, scheduled_at, client_data } =
    parsed.data

  try {
    const supabase = createPublicClient()
    const { data, error } = await supabase.rpc('public_create_booking', {
      p_token: token,
      p_studio_slug: studio_slug,
      p_service_id: service_id,
      p_artist_id: artist_id,
      p_scheduled_at: scheduled_at,
      p_client_data: client_data,
    })

    if (error) {
      logger.error({ err: error, studio_slug }, 'public booking create RPC failed')
      return NextResponse.json({ error: 'Failed to create booking' }, { status: 500 })
    }

    // RPC returns HTTP 200 always — check the payload for error key
    const result = data as Record<string, unknown>
    if (result && typeof result === 'object' && 'error' in result) {
      if (result.error === 'time_slot_unavailable') {
        return NextResponse.json(
          { error: 'That time slot is no longer available. Please choose another.' },
          { status: 409 }
        )
      }
      return NextResponse.json({ error: String(result.error) }, { status: 400 })
    }

    return NextResponse.json({ data }, { status: 201 })
  } catch (err) {
    logger.error({ err }, 'public booking POST unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { createPublicClient } from '@/lib/supabase/public'
import { publicBookingReadRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

interface Params {
  params: Promise<{ token: string }>
}

export async function GET(request: NextRequest, { params }: Params) {
  const ip = request.headers.get('x-forwarded-for') ?? 'anonymous'
  const { success } = await publicBookingReadRatelimit.limit(ip)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  const { token } = await params
  if (!z.string().uuid().safeParse(token).success) {
    return NextResponse.json({ error: 'Invalid token' }, { status: 400 })
  }

  try {
    const supabase = createPublicClient()
    const { data, error } = await supabase.rpc('public_get_booking_by_token', {
      p_token: token,
    })

    if (error) {
      logger.error({ err: error, token }, 'public booking lookup failed')
      return NextResponse.json({ error: 'Failed to fetch booking' }, { status: 500 })
    }

    if (!data) {
      return NextResponse.json({ error: 'Booking not found' }, { status: 404 })
    }

    return NextResponse.json({ data })
  } catch (err) {
    logger.error({ err }, 'public booking GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

'use client'

import type { EventApi } from '@fullcalendar/core'
import { cn } from '@/lib/utils'
import type { Database } from '@/lib/supabase/types'

type BookingStatus = Database['public']['Tables']['bookings']['Row']['status']

const STATUS_DOT_CLASSES: Partial<Record<BookingStatus, string>> = {
  in_progress: 'bg-[var(--color-status-in-progress)] animate-pulse',
  completed: 'bg-[var(--color-status-completed)]',
  cancelled: 'bg-[var(--color-status-cancelled)]',
  no_show: 'bg-[var(--color-status-no-show)]',
}

interface AppointmentCardProps {
  event: EventApi
}

export function AppointmentCard({ event }: AppointmentCardProps) {
  const status = event.extendedProps.status as BookingStatus
  const startTime = event.start
    ? event.start.toLocaleTimeString('en-US', {
        hour: 'numeric',
        minute: '2-digit',
        hour12: true,
      })
    : ''

  const dotClass = STATUS_DOT_CLASSES[status]
  const isCancelled = status === 'cancelled'

  return (
    <div className="relative flex h-full flex-col overflow-hidden px-1.5 py-0.5">
      <div className="flex items-center justify-between gap-1">
        <span
          className={cn(
            'text-[11px] font-medium truncate',
            isCancelled && 'line-through opacity-60'
          )}
        >
          {event.title}
        </span>
        <span className="text-[11px] tabular-nums shrink-0 opacity-70">{startTime}</span>
      </div>
      {event.extendedProps.serviceName && (
        <span className="text-[10px] opacity-60 truncate">
          {event.extendedProps.serviceName}
        </span>
      )}
      {dotClass && (
        <span
          aria-hidden="true"
          className={cn(
            'absolute bottom-1 right-1 h-1.5 w-1.5 rounded-full',
            dotClass
          )}
        />
      )}
    </div>
  )
}

