  sort_order: number
  colorClass: string
}

interface CalendarFilterRowProps {
  artists: Artist[]
  filterArtistIds: string[]
  filterStatuses: string[]
  onArtistFilterChange: (ids: string[]) => void
  onStatusFilterChange: (statuses: string[]) => void
}

export function CalendarFilterRow({
  artists,
  filterArtistIds,
  filterStatuses,
  onArtistFilterChange,
  onStatusFilterChange,
}: CalendarFilterRowProps) {
  const toggleArtist = (id: string) => {
    onArtistFilterChange(
      filterArtistIds.includes(id)
        ? filterArtistIds.filter((a) => a !== id)
        : [...filterArtistIds, id]
    )
  }

  const toggleStatus = (status: string) => {
    onStatusFilterChange(
      filterStatuses.includes(status)
        ? filterStatuses.filter((s) => s !== status)
        : [...filterStatuses, status]
    )
  }

  const artistLabel =
    filterArtistIds.length === 0
      ? 'All Artists'
      : filterArtistIds.length === 1
        ? artists.find((a) => a.id === filterArtistIds[0])?.display_name ?? '1 artist'
        : `${filterArtistIds.length} artists`

  const statusLabel =
    filterStatuses.length === 0 ? 'All Statuses' : `${filterStatuses.length} statuses`

  return (
    <div className="flex flex-wrap items-center gap-2 border-b border-border/30 px-4 py-2">
      {/* Artist filter */}
      <Popover>
        <PopoverTrigger asChild>
          <Button
            variant="ghost"
            size="sm"
            className={cn(
              'h-8 text-xs gap-1.5 text-muted-foreground hover:text-foreground',
              filterArtistIds.length > 0 && 'text-foreground bg-primary/10 border border-primary/20'
            )}
          >
            <Users2 className="h-3.5 w-3.5" />
            {artistLabel}
          </Button>
        </PopoverTrigger>
        <PopoverContent className="w-52 p-2" align="start">
          <div className="space-y-1">
            <button
              type="button"
              className="flex w-full items-center gap-2 rounded-md px-2 py-1.5 text-sm hover:bg-accent"
              onClick={() => onArtistFilterChange([])}
            >
              <span className="text-xs text-muted-foreground">All Artists</span>
            </button>
            {artists.map((artist) => (
              <div
                key={artist.id}
                className="flex items-center gap-2 rounded-md px-2 py-1.5 hover:bg-accent cursor-pointer"
                onClick={() => toggleArtist(artist.id)}
              >
                <Checkbox
                  id={`artist-${artist.id}`}
                  checked={filterArtistIds.includes(artist.id)}
                  onCheckedChange={() => toggleArtist(artist.id)}
                />
                <span className={cn('h-2.5 w-2.5 rounded-full shrink-0', artist.colorClass)} />
                <Label htmlFor={`artist-${artist.id}`} className="text-xs cursor-pointer flex-1">
                  {artist.display_name}
                </Label>
              </div>
            ))}
          </div>
        </PopoverContent>
      </Popover>

      {/* Status filter */}
      <Popover>
        <PopoverTrigger asChild>
          <Button
            variant="ghost"
            size="sm"
            className={cn(
              'h-8 text-xs gap-1.5 text-muted-foreground hover:text-foreground',
              filterStatuses.length > 0 && 'text-foreground bg-primary/10 border border-primary/20'
            )}
          >
            <Circle className="h-3.5 w-3.5" />
            {statusLabel}
          </Button>
        </PopoverTrigger>
        <PopoverContent className="w-48 p-2" align="start">
          <div className="space-y-1">
            {STATUSES.map(({ value, label }) => (
              <div
                key={value}
                className="flex items-center gap-2 rounded-md px-2 py-1.5 hover:bg-accent cursor-pointer"
                onClick={() => toggleStatus(value)}
              >
                <Checkbox
                  id={`status-${value}`}
                  checked={filterStatuses.includes(value)}
                  onCheckedChange={() => toggleStatus(value)}
                />
                <span className={cn('h-2 w-2 rounded-full shrink-0', STATUS_DOT_CLASSES[value])} />
                <Label htmlFor={`status-${value}`} className="text-xs cursor-pointer flex-1">
                  {label}
                </Label>
              </div>
            ))}
          </div>
        </PopoverContent>
      </Popover>
    </div>
  )
}

