import { useState, useEffect } from 'react'
import { useQuery } from '@tanstack/react-query'
import { Calendar } from '@/components/ui/calendar'
import { Skeleton } from '@/components/ui/skeleton'
import { cn } from '@/lib/utils'
import { AlertCircle } from 'lucide-react'

interface Slot {
  start: string
  end: string
}

interface AvailabilityData {
  date: string
  artist_id: string
  duration_min: number
  slots: Slot[]
}

interface SlotPickerProps {
  artistId: string | null
  serviceId: string | null
  selectedSlot: string | null
  onSelectSlot: (isoStart: string) => void
}

export function SlotPicker({
  artistId,
  serviceId,
  selectedSlot,
  onSelectSlot,
}: SlotPickerProps) {
  const [selectedDate, setSelectedDate] = useState<Date | undefined>(new Date())

  // Reset selected slot when date changes
  useEffect(() => {
    onSelectSlot('')
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedDate])

  const dateStr = selectedDate
    ? `${selectedDate.getFullYear()}-${String(selectedDate.getMonth() + 1).padStart(2, '0')}-${String(selectedDate.getDate()).padStart(2, '0')}`
    : null

  const { data, isLoading, error } = useQuery<{ data: AvailabilityData }>({
    queryKey: ['availability', artistId, serviceId, dateStr],
    queryFn: async () => {
      const params = new URLSearchParams({
        artist_id: artistId!,
        service_id: serviceId!,
        date: dateStr!,
      })
      const res = await fetch(`/api/public/availability?${params.toString()}`)
      if (!res.ok) throw new Error('Failed to fetch availability')
      return res.json() as Promise<{ data: AvailabilityData }>
    },
    enabled: Boolean(artistId && serviceId && dateStr),
  })

  const slots = data?.data?.slots ?? []

  return (
    <div className="space-y-4">
      <div className="flex justify-center">
        <Calendar
          mode="single"
          selected={selectedDate}
          onSelect={setSelectedDate}
          disabled={(date) => date < new Date(new Date().setHours(0, 0, 0, 0))}
          className="rounded-lg border border-border"
        />
      </div>

      {!artistId || !serviceId ? (
        <p className="text-center text-sm text-muted-foreground py-4">
          Select a service and artist first
        </p>
      ) : isLoading ? (
        <div className="grid grid-cols-3 gap-2">
          {Array.from({ length: 9 }).map((_, i) => (
            <Skeleton key={i} className="h-10 rounded-md" />
          ))}
        </div>
      ) : error ? (
        <div className="flex items-center gap-2 text-sm text-destructive py-2">
          <AlertCircle className="h-4 w-4 shrink-0" />
          Failed to load availability
        </div>
      ) : slots.length === 0 ? (
        <p className="text-center text-sm text-muted-foreground py-4">
          No available slots for this date
        </p>
      ) : (
        <div className="grid grid-cols-3 gap-2">
          {slots.map((slot) => {
            const time = new Date(slot.start).toLocaleTimeString('en-US', {
              hour: 'numeric',
              minute: '2-digit',
              hour12: true,
            })
            const isSelected = selectedSlot === slot.start
            return (
              <button
                key={slot.start}
                type="button"
                data-selected={isSelected ? 'true' : 'false'}
                data-disabled="false"
                className={cn(
                  'time-slot rounded-md border px-2 py-2 text-xs font-medium tabular-nums',
                  'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
                  isSelected
                    ? 'border-[var(--color-booking-step-active)] bg-primary/10 text-primary'
                    : 'border-border bg-background text-foreground'
                )}
                onClick={() => onSelectSlot(slot.start)}
              >
                {time}
              </button>
            )
          })}
        </div>
      )}
    </div>
  )
}

