  const [newClient, setNewClient] = useState<NewClientData>({
    first_name: '',
    last_name: '',
    email: '',
    phone: '',
  })

  const debouncedQuery = useDebounce(query, 300)
  const inputRef = useRef<HTMLInputElement>(null)

  useEffect(() => {
    if (!debouncedQuery.trim() || debouncedQuery.length < 2) {
      setResults([])
      return
    }
    setIsSearching(true)
    fetch(`/api/clients/search?q=${encodeURIComponent(debouncedQuery)}&limit=10`)
      .then((r) => r.json() as Promise<{ data: Client[] }>)
      .then((data) => setResults(data.data ?? []))
      .catch(() => setResults([]))
      .finally(() => setIsSearching(false))
  }, [debouncedQuery])

  if (selectedClientId && selectedName) {
    return (
      <div className="flex items-center justify-between rounded-lg border border-primary/40 bg-primary/6 px-3 py-2">
        <div className="flex items-center gap-2 text-sm">
          <div className="h-6 w-6 rounded-full bg-primary/20 flex items-center justify-center">
            <Check className="h-3.5 w-3.5 text-primary" />
          </div>
          <span className="font-medium">{selectedName}</span>
        </div>
        <button
          type="button"
          className="text-xs text-muted-foreground hover:text-foreground"
          onClick={() => {
            setSelectedName(null)
            onSelectClient('', '')
            setQuery('')
            setTimeout(() => inputRef.current?.focus(), 50)
          }}
        >
          Change
        </button>
      </div>
    )
  }

  return (
    <div className="space-y-3">
      <div className="relative">
        <Search className="absolute left-2.5 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-muted-foreground pointer-events-none" />
        <Input
          ref={inputRef}
          type="text"
          placeholder="Search by name, email, or phone..."
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          className="pl-8 text-sm h-9"
        />
      </div>

      {/* Search results */}
      {query.length >= 2 && (
        <div className="rounded-lg border border-border divide-y divide-border/50 overflow-hidden">
          {isSearching && (
            <div className="p-2 space-y-2">
              <Skeleton className="h-9" />
              <Skeleton className="h-9" />
            </div>
          )}

          {!isSearching && results.map((client) => (
            <button
              key={client.id}
              type="button"
              className="flex w-full items-center gap-3 px-3 py-2.5 text-left hover:bg-accent transition-colors"
              onClick={() => {
                const name = `${client.first_name} ${client.last_name ?? ''}`.trim()
                setSelectedName(name)
                onSelectClient(client.id, name)
                setQuery('')
              }}
            >
              <div className="h-8 w-8 rounded-full bg-muted flex items-center justify-center text-xs font-medium shrink-0">
                {client.first_name[0]}{client.last_name?.[0] ?? ''}
              </div>
              <div className="min-w-0">
                <p className="text-sm font-medium truncate">
                  {client.first_name} {client.last_name ?? ''}
                </p>
                <p className="text-xs text-muted-foreground truncate">
                  {client.email ?? client.phone ?? `${client.total_sessions} sessions`}
                </p>
              </div>
            </button>
          ))}

          {!isSearching && results.length === 0 && (
            <div className="p-3 text-center text-sm text-muted-foreground">
              No clients found
            </div>
          )}

          {/* Create new option */}
          <button
            type="button"
            className="flex w-full items-center gap-2 px-3 py-2.5 text-sm text-primary hover:bg-primary/8 transition-colors"
            onClick={() => {
              setShowCreateForm(true)
              setNewClient((prev) => ({ ...prev, first_name: query }))
            }}
          >
            <UserPlus className="h-4 w-4" />
            Add new client
          </button>
        </div>
      )}

      {/* Create new client inline form */}
      {showCreateForm && (
        <div className="rounded-lg border border-border p-3 space-y-3 bg-muted/30">
          <p className="text-sm font-medium">New client</p>
          <div className="grid grid-cols-2 gap-2">
            <div className="space-y-1">
              <Label className="text-xs">First name *</Label>
              <Input
                value={newClient.first_name}
                onChange={(e) => setNewClient((p) => ({ ...p, first_name: e.target.value }))}
                className="h-8 text-sm"
                placeholder="Jane"
              />
            </div>
            <div className="space-y-1">
              <Label className="text-xs">Last name</Label>
              <Input
                value={newClient.last_name}
                onChange={(e) => setNewClient((p) => ({ ...p, last_name: e.target.value }))}
                className="h-8 text-sm"
                placeholder="Smith"
              />
            </div>
          </div>
          <div className="grid grid-cols-2 gap-2">
            <div className="space-y-1">
              <Label className="text-xs">Email</Label>
              <Input
                type="email"
                value={newClient.email}
                onChange={(e) => setNewClient((p) => ({ ...p, email: e.target.value }))}
                className="h-8 text-sm"
                placeholder="jane@example.com"
              />
            </div>
            <div className="space-y-1">
              <Label className="text-xs">Phone</Label>
              <Input
                type="tel"
                value={newClient.phone}
                onChange={(e) => setNewClient((p) => ({ ...p, phone: e.target.value }))}
                className="h-8 text-sm"
                placeholder="+1 555 000 0000"
              />
            </div>
          </div>
          <div className="flex gap-2">
            <button
              type="button"
              className="flex-1 rounded-md bg-primary px-3 py-1.5 text-xs font-medium text-primary-foreground hover:bg-primary/90 disabled:opacity-50"
              disabled={!newClient.first_name.trim()}
              onClick={() => {
                onNewClient(newClient)
                setShowCreateForm(false)
                const name = `${newClient.first_name} ${newClient.last_name ?? ''}`.trim()
                setSelectedName(name)
                setQuery('')
              }}
            >
              Add client
            </button>
            <button
              type="button"
              className="rounded-md border border-border px-3 py-1.5 text-xs text-muted-foreground hover:text-foreground"
              onClick={() => setShowCreateForm(false)}
