              Cancel
            </button>
          </div>
        </div>
      )}
    </div>
  )
}

import { useState, useEffect } from 'react'

/**
 * Debounces a value by the given delay in ms.
 */
export function useDebounce<T>(value: T, delay: number): T {
  const [debouncedValue, setDebouncedValue] = useState<T>(value)

  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedValue(value)
    }, delay)

    return () => {
      clearTimeout(timer)
    }
  }, [value, delay])

  return debouncedValue
}

'use client'

import { useState, useEffect } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetDescription,
} from '@/components/ui/sheet'
import { Button } from '@/components/ui/button'
import { Skeleton } from '@/components/ui/skeleton'
import { BookingStepIndicator } from '@/components/booking/BookingStepIndicator'
import { ServicePicker } from '@/components/booking/ServicePicker'
import { ArtistPicker } from '@/components/booking/ArtistPicker'
import { SlotPicker } from '@/components/booking/SlotPicker'
import { ClientFinder } from '@/components/booking/ClientFinder'
import { Textarea } from '@/components/ui/textarea'
import { Label } from '@/components/ui/label'
import { toast } from 'sonner'
import { logger } from '@/lib/logger'
import { formatCurrency } from '@/lib/utils'

interface AppointmentDrawerProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  editingId: string | null
  defaultStart?: Date
  defaultEnd?: Date
  onSuccess: () => void
}

const CREATE_STEPS = [
  { label: 'Service' },
  { label: 'Artist' },
  { label: 'Time' },
  { label: 'Client' },
]

interface Service {
  id: string
  name: string
  description: string | null
  duration_min: number
  base_price_cents: number
  deposit_cents: number
  deposit_required: boolean
  color: string | null
}

interface Artist {
  id: string
  display_name: string
  avatar_url: string | null
  sort_order: number
  specialties: string[]
}

export function AppointmentDrawer({
  open,
  onOpenChange,
  editingId,
  defaultStart,
  onSuccess,
}: AppointmentDrawerProps) {
  const queryClient = useQueryClient()
  const isCreating = !editingId

  // Create flow state
  const [step, setStep] = useState(0)
  const [selectedServiceId, setSelectedServiceId] = useState<string | null>(null)
  const [selectedArtistId, setSelectedArtistId] = useState<string | null>(null)
  const [selectedSlot, setSelectedSlot] = useState<string | null>(null)
  const [selectedClientId, setSelectedClientId] = useState<string | null>(null)
  const [newClientData, setNewClientData] = useState<{
    first_name: string; last_name: string; email: string; phone: string
  } | null>(null)
  const [notes, setNotes] = useState('')

  // Reset on open/close
  useEffect(() => {
    if (open && isCreating) {
      setStep(0)
      setSelectedServiceId(null)
      setSelectedArtistId(null)
      setSelectedSlot(defaultStart ? defaultStart.toISOString() : null)
      setSelectedClientId(null)
      setNewClientData(null)
      setNotes('')
    }
  }, [open, isCreating, defaultStart])

  // Services query
  const { data: servicesData, isLoading: servicesLoading } = useQuery<{ data: Service[] }>({
    queryKey: ['services'],
    queryFn: async () => {
      const res = await fetch('/api/services')
      if (!res.ok) throw new Error('Failed to fetch services')
      return res.json() as Promise<{ data: Service[] }>
    },
    enabled: open && isCreating,
  })

  // Artists filtered by service
  const { data: artistsData, isLoading: artistsLoading } = useQuery<{ data: Artist[] }>({
    queryKey: ['artists', 'by-service', selectedServiceId],
    queryFn: async () => {
      const url = selectedServiceId
        ? `/api/artists?service_id=${selectedServiceId}&status=active`
        : '/api/artists?status=active'
      const res = await fetch(url)
      if (!res.ok) throw new Error('Failed to fetch artists')
      return res.json() as Promise<{ data: Artist[] }>
    },
    enabled: open && isCreating && step >= 1,
  })

  // Edit mode: fetch booking details
  const { data: editData, isLoading: editLoading } = useQuery<{ data: unknown }>({
    queryKey: ['booking', editingId],
    queryFn: async () => {
      const res = await fetch(`/api/bookings/${editingId}`)
      if (!res.ok) throw new Error('Failed to fetch booking')
      return res.json() as Promise<{ data: unknown }>
    },
    enabled: Boolean(open && editingId),
  })

  const createMutation = useMutation({
    mutationFn: async () => {
      // If new client, create them first
      let clientId = selectedClientId
      if (!clientId && newClientData) {
        const res = await fetch('/api/clients', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(newClientData),
        })
        if (!res.ok) {
          const err = await res.json() as { error?: string }
          throw new Error(err.error ?? 'Failed to create client')
        }
        const { data } = await res.json() as { data: { id: string } }
        clientId = data.id
      }

      if (!clientId || !selectedArtistId || !selectedSlot || !selectedServiceId) {
        throw new Error('All fields are required')
      }

      const service = servicesData?.data.find((s) => s.id === selectedServiceId)
      const res = await fetch('/api/bookings', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          client_id: clientId,
          artist_id: selectedArtistId,
          service_id: selectedServiceId,
          scheduled_at: selectedSlot,
          duration_min: service?.duration_min ?? 60,
          price_cents: service?.base_price_cents ?? 0,
          deposit_cents: service?.deposit_cents ?? 0,
          notes: notes || undefined,
          source: 'internal',
        }),
      })

      if (!res.ok) {
        const err = await res.json() as { error?: string }
        if (err.error?.includes('time slot') || err.error?.includes('23P01')) {
          throw new Error('That time slot is already booked for this artist')
        }
        throw new Error(err.error ?? 'Failed to create booking')
      }
    },
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: ['bookings'] })
      onSuccess()
    },
    onError: (err: Error) => {
      toast.error(err.message)
      logger.error({ err }, 'appointment create failed')
    },
  })

  const services = servicesData?.data ?? []
  const artists = artistsData?.data ?? []
  const selectedService = services.find((s) => s.id === selectedServiceId)

  // Step validation
  const canProceed =
    (step === 0 && !!selectedServiceId) ||
    (step === 1 && !!selectedArtistId) ||
    (step === 2 && !!selectedSlot) ||
    (step === 3 && (!!selectedClientId || !!newClientData))

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent
        side="right"
        className="w-full sm:max-w-lg flex flex-col overflow-hidden p-0"
      >
        <SheetHeader className="px-6 pt-6 pb-4 border-b border-border/40">
          <SheetTitle>{editingId ? 'Edit Appointment' : 'New Appointment'}</SheetTitle>
          <SheetDescription className="sr-only">
            {editingId ? 'Modify appointment details' : 'Book a new appointment'}
          </SheetDescription>
          {isCreating && (
            <BookingStepIndicator steps={CREATE_STEPS} currentStep={step} className="mt-3" />
          )}
        </SheetHeader>

        <div className="flex-1 overflow-y-auto px-6 py-4 space-y-4">
          {/* Create flow */}
          {isCreating && (
            <>
              {step === 0 && (
                <div
                  className="space-y-3"
                  style={{ animationFillMode: 'both' }}
                >
                  <p className="text-sm font-medium">Choose a service</p>
                  <ServicePicker
                    services={services}
                    selectedId={selectedServiceId}
                    onSelect={setSelectedServiceId}
                    isLoading={servicesLoading}
                  />
                </div>
              )}

              {step === 1 && (
                <div className="space-y-3" style={{ animationFillMode: 'both' }}>
                  <p className="text-sm font-medium">Choose an artist</p>
                  {selectedService && (
                    <p className="text-xs text-muted-foreground">
                      For: {selectedService.name} ({selectedService.duration_min} min)
                    </p>
                  )}
                  <ArtistPicker
                    artists={artists}
                    selectedId={selectedArtistId}
                    onSelect={setSelectedArtistId}
                    isLoading={artistsLoading}
                  />
                </div>
              )}

              {step === 2 && (
                <div className="space-y-3" style={{ animationFillMode: 'both' }}>
                  <p className="text-sm font-medium">Pick a time</p>
                  <SlotPicker
                    artistId={selectedArtistId}
                    serviceId={selectedServiceId}
                    selectedSlot={selectedSlot}
                    onSelectSlot={setSelectedSlot}
                  />
                </div>
              )}

              {step === 3 && (
                <div className="space-y-4" style={{ animationFillMode: 'both' }}>
                  <div className="space-y-3">
                    <p className="text-sm font-medium">Find or add a client</p>
                    <ClientFinder
                      selectedClientId={selectedClientId}
                      onSelectClient={(id) => setSelectedClientId(id)}
                      onNewClient={(data) => {
                        setNewClientData(data)
                        setSelectedClientId(null)
                      }}
                    />
                  </div>

                  {/* Summary */}
                  {selectedService && selectedSlot && (
                    <div className="rounded-lg bg-muted/40 border border-border/60 p-3 space-y-1.5 text-sm">
                      <p className="font-medium text-xs text-muted-foreground uppercase tracking-wide">
                        Summary
                      </p>
                      <p>{selectedService.name}</p>
                      <p className="tabular-nums text-xs text-muted-foreground">
                        {new Date(selectedSlot).toLocaleDateString('en-US', {
                          weekday: 'short',
                          month: 'short',
                          day: 'numeric',
                          hour: '2-digit',
                          minute: '2-digit',
                        })}
                      </p>
                      <p className="tabular-nums font-medium">
                        {formatCurrency(selectedService.base_price_cents)}
                      </p>
                    </div>
                  )}

                  <div className="space-y-1">
                    <Label className="text-xs">Internal notes (optional)</Label>
                    <Textarea
                      value={notes}
                      onChange={(e) => setNotes(e.target.value)}
                      placeholder="Notes visible only to staff..."
                      className="text-sm min-h-[80px] resize-none"
                      maxLength={2000}
                    />
                  </div>
                </div>
              )}
            </>
          )}

          {/* Edit mode */}
          {!isCreating && (
            <div className="space-y-4">
              {editLoading ? (
                <div className="space-y-3">
                  <Skeleton className="h-12 w-full" />
                  <Skeleton className="h-12 w-full" />
                  <Skeleton className="h-12 w-2/3" />
                </div>
              ) : (
                <p className="text-sm text-muted-foreground">
                  Edit functionality available in appointment detail page.
                </p>
              )}
            </div>
          )}
        </div>

        {/* Footer actions */}
        <div className="border-t border-border/40 px-6 py-4 flex items-center justify-between gap-3">
          <Button
            variant="outline"
            onClick={() => {
              if (isCreating && step > 0) {
                setStep((s) => s - 1)
              } else {
                onOpenChange(false)
              }
            }}
          >
            {isCreating && step > 0 ? 'Back' : 'Cancel'}
          </Button>

          {isCreating && step < CREATE_STEPS.length - 1 && (
            <Button disabled={!canProceed} onClick={() => setStep((s) => s + 1)}>
              Next
            </Button>
          )}

          {isCreating && step === CREATE_STEPS.length - 1 && (
            <Button
              disabled={!canProceed || createMutation.isPending}
              onClick={() => createMutation.mutate()}
            >
              {createMutation.isPending ? 'Booking...' : 'Book Appointment'}
            </Button>
          )}
        </div>
      </SheetContent>
    </Sheet>
  )
}

'use client'

import { useState, useTransition, useCallback } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import { Checkbox } from '@/components/ui/checkbox'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Skeleton } from '@/components/ui/skeleton'
import { AppointmentStatusBadge } from './AppointmentStatusBadge'
import { useDebounce } from '@/hooks/useDebounce'
import { formatCurrency, formatDate } from '@/lib/utils'
import { toast } from 'sonner'
import { logger } from '@/lib/logger'
import { Search, Download, Check, X, ChevronLeft, ChevronRight, CalendarPlus } from 'lucide-react'
import { useRouter } from 'next/navigation'
import Papa from 'papaparse'
import type { Database } from '@/lib/supabase/types'

type BookingStatus = Database['public']['Tables']['bookings']['Row']['status']

interface BookingRow {
  id: string
  scheduled_at: string
  end_at: string
  duration_min: number
  status: BookingStatus
  price_cents: number
  deposit_paid: boolean
  booking_token: string
  source: string
  created_at: string
  client: { id: string; first_name: string; last_name: string | null; email: string | null } | null
  artist: { id: string; display_name: string; sort_order: number } | null
  service: { id: string; name: string; color: string | null } | null
}

interface BookingsResponse {
  data: BookingRow[]
  count: number
  page: number
  per_page: number
  total_pages: number
}

interface AppointmentsTableProps {
  onNewAppointment: () => void
}

const PER_PAGE = 25

export function AppointmentsTable({ onNewAppointment }: AppointmentsTableProps) {
  const router = useRouter()
  const queryClient = useQueryClient()
  const [search, setSearch] = useState('')
  const [page, setPage] = useState(1)
  const [statusFilter, setStatusFilter] = useState<BookingStatus | ''>('')
  const [selectedIds, setSelectedIds] = useState<string[]>([])
  const [, startTransition] = useTransition()

  const debouncedSearch = useDebounce(search, 300)

  const { data, isLoading, error } = useQuery<BookingsResponse>({
    queryKey: ['bookings', 'table', debouncedSearch, statusFilter, page],
    queryFn: async () => {
      const params = new URLSearchParams({ per_page: String(PER_PAGE), page: String(page) })
      if (debouncedSearch) params.set('q', debouncedSearch)
      if (statusFilter) params.set('status', statusFilter)
      const res = await fetch(`/api/bookings?${params.toString()}`)
      if (!res.ok) throw new Error('Failed to fetch appointments')
      return res.json() as Promise<BookingsResponse>
    },
  })

  const bulkStatusMutation = useMutation({
    mutationFn: async ({ ids, status }: { ids: string[]; status: BookingStatus }) => {
      await Promise.all(
        ids.map((id) =>
          fetch(`/api/bookings/${id}/status`, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ status }),
          }).then(async (res) => {
            if (!res.ok) {
              const err = await res.json() as { error?: string }
              throw new Error(err.error ?? `Failed to update ${id}`)
            }
          })
        )
      )
    },
    onSuccess: (_data, { status }) => {
      void queryClient.invalidateQueries({ queryKey: ['bookings'] })
      setSelectedIds([])
      toast.success(`${selectedIds.length} appointment${selectedIds.length > 1 ? 's' : ''} ${status}`)
    },
    onError: (err: Error) => {
      toast.error(err.message)
      logger.error({ err }, 'bulk status update failed')
    },
  })

  const bookings = data?.data ?? []
  const totalPages = data?.total_pages ?? 1
  const totalCount = data?.count ?? 0

  const toggleSelectAll = useCallback(() => {
    if (selectedIds.length === bookings.length) {
      setSelectedIds([])
    } else {
      setSelectedIds(bookings.map((b) => b.id))
    }
  }, [selectedIds.length, bookings])

  const toggleSelect = useCallback((id: string) => {
    setSelectedIds((prev) =>
      prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id]
    )
  }, [])

  const handleExportCSV = useCallback(() => {
    const rows = (selectedIds.length > 0 ? bookings.filter((b) => selectedIds.includes(b.id)) : bookings).map((b) => ({
      ID: b.id,
      Date: formatDate(b.scheduled_at),
      Time: new Date(b.scheduled_at).toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' }),
      Client: b.client ? `${b.client.first_name} ${b.client.last_name ?? ''}`.trim() : '',
      Email: b.client?.email ?? '',
      Artist: b.artist?.display_name ?? '',
      Service: b.service?.name ?? '',
      Status: b.status,
      Price: (b.price_cents / 100).toFixed(2),
      'Deposit Paid': b.deposit_paid ? 'Yes' : 'No',
      Source: b.source,
    }))

    const csv = Papa.unparse(rows)
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `appointments-${new Date().toISOString().split('T')[0]}.csv`
    a.click()
    URL.revokeObjectURL(url)
    toast.success('Exported to CSV')
  }, [bookings, selectedIds])

  const STATUS_OPTIONS: { value: BookingStatus | ''; label: string }[] = [
    { value: '', label: 'All statuses' },
    { value: 'pending', label: 'Pending' },
    { value: 'confirmed', label: 'Confirmed' },
    { value: 'in_progress', label: 'In Progress' },
    { value: 'completed', label: 'Completed' },
    { value: 'cancelled', label: 'Cancelled' },
    { value: 'no_show', label: 'No Show' },
  ]

  if (error) {
    return (
      <div className="p-6 text-center">
        <p className="text-sm text-destructive">Failed to load appointments</p>
        <Button
          variant="outline"
          size="sm"
          className="mt-3"
          onClick={() => void queryClient.invalidateQueries({ queryKey: ['bookings', 'table'] })}
        >
          Retry
        </Button>
      </div>
    )
  }

  return (
    <div className="flex flex-col flex-1 overflow-hidden">
      {/* Toolbar */}
      <div className="flex flex-wrap items-center gap-2 px-6 py-3 border-b border-border/40">
        <div className="relative flex-1 min-w-48 max-w-72">
          <Search className="absolute left-2.5 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-muted-foreground pointer-events-none" />
          <Input
            value={search}
            onChange={(e) => {
              setSearch(e.target.value)
              startTransition(() => setPage(1))
            }}
            placeholder="Search appointments..."
            className="pl-8 h-8 text-sm"
          />
        </div>

        <select
          value={statusFilter}
          onChange={(e) => {
            setStatusFilter(e.target.value as BookingStatus | '')
            startTransition(() => setPage(1))
          }}
          className="h-8 rounded-md border border-input bg-background px-2 text-xs text-foreground"
        >
          {STATUS_OPTIONS.map((o) => (
            <option key={o.value} value={o.value}>{o.label}</option>
          ))}
        </select>

        <div className="flex items-center gap-2 ml-auto">
          {selectedIds.length > 0 && (
            <>
              <span className="text-xs text-muted-foreground">{selectedIds.length} selected</span>
              <Button
                variant="outline"
                size="sm"
                className="h-8 text-xs gap-1.5"
                disabled={bulkStatusMutation.isPending}
                onClick={() =>
                  bulkStatusMutation.mutate({ ids: selectedIds, status: 'confirmed' })
                }
              >
                <Check className="h-3.5 w-3.5" />
                Confirm
              </Button>
              <Button
                variant="outline"
                size="sm"
                className="h-8 text-xs gap-1.5 text-destructive hover:text-destructive"
                disabled={bulkStatusMutation.isPending}
                onClick={() =>
                  bulkStatusMutation.mutate({ ids: selectedIds, status: 'cancelled' })
                }
              >
                <X className="h-3.5 w-3.5" />
                Cancel
              </Button>
            </>
          )}

          <Button
            variant="outline"
            size="sm"
            className="h-8 text-xs gap-1.5"
            onClick={handleExportCSV}
          >
            <Download className="h-3.5 w-3.5" />
            Export
          </Button>

          <Button size="sm" className="h-8 text-xs" onClick={onNewAppointment}>
            New
          </Button>
        </div>
      </div>

      {/* Table */}
      <div className="flex-1 overflow-auto">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead className="w-10">
                <Checkbox
                  checked={selectedIds.length === bookings.length && bookings.length > 0}
                  onCheckedChange={toggleSelectAll}
                  aria-label="Select all"
                />
              </TableHead>
              <TableHead>Date & Time</TableHead>
              <TableHead>Client</TableHead>
              <TableHead>Artist</TableHead>
              <TableHead>Service</TableHead>
              <TableHead>Status</TableHead>
              <TableHead className="text-right">Price</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {isLoading &&
              Array.from({ length: 8 }).map((_, i) => (
                <TableRow key={i}>
                  <TableCell><Skeleton className="h-4 w-4" /></TableCell>
                  <TableCell><Skeleton className="h-4 w-28" /></TableCell>
                  <TableCell><Skeleton className="h-4 w-24" /></TableCell>
                  <TableCell><Skeleton className="h-4 w-20" /></TableCell>
                  <TableCell><Skeleton className="h-4 w-24" /></TableCell>
                  <TableCell><Skeleton className="h-5 w-16 rounded-full" /></TableCell>
                  <TableCell><Skeleton className="h-4 w-12 ml-auto" /></TableCell>
                </TableRow>
              ))}

            {!isLoading && bookings.length === 0 && (
              <TableRow>
                <TableCell colSpan={7} className="py-16 text-center">
                  <div className="flex flex-col items-center gap-3">
                    <div className="rounded-xl bg-muted/50 p-3">
                      <CalendarPlus className="h-8 w-8 text-muted-foreground/50" />
                    </div>
                    <div className="space-y-1">
                      <p className="text-sm font-medium">
                        {search || statusFilter ? 'No appointments match your filters' : 'No appointments yet'}
                      </p>
                      <p className="text-xs text-muted-foreground">
                        {search || statusFilter
                          ? 'Try adjusting your search or filter'
                          : 'Book your first appointment to get started'}
                      </p>
                    </div>
                    {!search && !statusFilter && (
                      <Button size="sm" onClick={onNewAppointment}>
                        New appointment
                      </Button>
                    )}
                  </div>
                </TableCell>
              </TableRow>
            )}

            {!isLoading &&
              bookings.map((booking) => (
                <TableRow
                  key={booking.id}
                  className="cursor-pointer hover:bg-muted/50"
                  onClick={() => router.push(`/appointments/${booking.id}`)}
                >
                  <TableCell
                    onClick={(e) => {
                      e.stopPropagation()
                      toggleSelect(booking.id)
                    }}
                  >
                    <Checkbox
                      checked={selectedIds.includes(booking.id)}
                      onCheckedChange={() => toggleSelect(booking.id)}
                      aria-label={`Select booking ${booking.id}`}
                    />
                  </TableCell>
                  <TableCell className="tabular-nums text-sm">
                    <div className="font-medium">
                      {new Date(booking.scheduled_at).toLocaleDateString('en-US', {
                        month: 'short',
                        day: 'numeric',
                        year: 'numeric',
                      })}
                    </div>
                    <div className="text-xs text-muted-foreground">
                      {new Date(booking.scheduled_at).toLocaleTimeString('en-US', {
                        hour: '2-digit',
                        minute: '2-digit',
                      })}
                    </div>
                  </TableCell>
                  <TableCell>
                    {booking.client ? (
                      <div>
                        <p className="text-sm font-medium">
                          {booking.client.first_name} {booking.client.last_name ?? ''}
                        </p>
                        {booking.client.email && (
                          <p className="text-xs text-muted-foreground truncate max-w-[160px]">
                            {booking.client.email}
                          </p>
                        )}
                      </div>
                    ) : (
                      <span className="text-xs text-muted-foreground">—</span>
                    )}
                  </TableCell>
                  <TableCell>
                    <span className="text-sm">
                      {booking.artist?.display_name ?? '—'}
                    </span>
                  </TableCell>
                  <TableCell>
                    {booking.service ? (
                      <div className="flex items-center gap-1.5">
                        {booking.service.color && (
                          <span
                            className="h-2 w-2 rounded-full shrink-0"
                            style={{ backgroundColor: booking.service.color }}
                          />
                        )}
                        <span className="text-sm truncate max-w-[140px]">
                          {booking.service.name}
                        </span>
                      </div>
                    ) : (
                      <span className="text-xs text-muted-foreground">—</span>
                    )}
                  </TableCell>
                  <TableCell>
                    <AppointmentStatusBadge status={booking.status} />
                  </TableCell>
                  <TableCell className="text-right tabular-nums text-sm font-medium">
                    {formatCurrency(booking.price_cents)}
                  </TableCell>
                </TableRow>
              ))}
          </TableBody>
        </Table>
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex items-center justify-between border-t border-border/40 px-6 py-3">
          <p className="text-xs text-muted-foreground tabular-nums">
            {(page - 1) * PER_PAGE + 1}–{Math.min(page * PER_PAGE, totalCount)} of {totalCount}
          </p>
          <div className="flex items-center gap-1">
            <Button
              variant="ghost"
              size="icon"
              className="h-7 w-7"
              disabled={page === 1}
              onClick={() => setPage((p) => p - 1)}
              aria-label="Previous page"
            >
              <ChevronLeft className="h-4 w-4" />
            </Button>
            <span className="text-xs tabular-nums px-2">
              {page} / {totalPages}
            </span>
            <Button
              variant="ghost"
              size="icon"
              className="h-7 w-7"
              disabled={page === totalPages}
              onClick={() => setPage((p) => p + 1)}
              aria-label="Next page"
            >
              <ChevronRight className="h-4 w-4" />
            </Button>
          </div>
        </div>
      )}
    </div>
  )
}

