'use client'

import { useState, useCallback } from 'react'
import { useMutation, useQueryClient } from '@tanstack/react-query'
import { Button } from '@/components/ui/button'
import { Textarea } from '@/components/ui/textarea'
import { toast } from 'sonner'
import { logger } from '@/lib/logger'
import { FileText, Pencil, X, Check } from 'lucide-react'
import { cn } from '@/lib/utils'

interface SessionNotesProps {
  bookingId: string
  notes: string | null
  label?: string
  field?: 'notes' | 'client_notes'
  className?: string
}

export function SessionNotes({
  bookingId,
  notes,
  label = 'Internal notes',
  field = 'notes',
  className,
}: SessionNotesProps) {
  const queryClient = useQueryClient()
  const [editing, setEditing] = useState(false)
  const [draft, setDraft] = useState(notes ?? '')

  const mutation = useMutation({
    mutationFn: async (value: string) => {
      const res = await fetch(`/api/bookings/${bookingId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ [field]: value || null }),
      })
      if (!res.ok) {
        const err = await res.json() as { error?: string }
        throw new Error(err.error ?? 'Failed to save notes')
      }
    },
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: ['booking', bookingId] })
      setEditing(false)
      toast.success('Notes saved')
    },
    onError: (err: Error) => {
      toast.error(err.message)
      logger.error({ err, bookingId }, 'session notes save failed')
    },
  })

  const handleSave = useCallback(() => {
    mutation.mutate(draft)
  }, [draft, mutation])

  const handleCancel = useCallback(() => {
    setDraft(notes ?? '')
    setEditing(false)
  }, [notes])

  return (
    <div className={cn('space-y-2', className)}>
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-1.5">
          <FileText className="h-3.5 w-3.5 text-muted-foreground" />
          <span className="text-xs font-medium text-muted-foreground uppercase tracking-wider">
            {label}
          </span>
        </div>
        {!editing && (
          <Button
            variant="ghost"
            size="icon"
            className="h-6 w-6"
            onClick={() => {
              setDraft(notes ?? '')
              setEditing(true)
            }}
          >
            <Pencil className="h-3 w-3" />
            <span className="sr-only">Edit {label}</span>
          </Button>
        )}
      </div>

      {editing ? (
        <div className="space-y-2">
          <Textarea
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            placeholder={`Add ${label.toLowerCase()}...`}
            className="text-sm min-h-[100px] resize-none"
            maxLength={2000}
            autoFocus
          />
          <div className="flex items-center gap-2">
            <Button
              size="sm"
              className="h-7 text-xs gap-1.5"
              disabled={mutation.isPending}
              onClick={handleSave}
            >
              <Check className="h-3.5 w-3.5" />
              {mutation.isPending ? 'Saving...' : 'Save'}
            </Button>
            <Button
              variant="ghost"
              size="sm"
              className="h-7 text-xs gap-1.5"
              disabled={mutation.isPending}
              onClick={handleCancel}
            >
              <X className="h-3.5 w-3.5" />
              Cancel
            </Button>
            {draft.length > 0 && (
              <span className="ml-auto text-xs text-muted-foreground tabular-nums">
                {draft.length}/2000
              </span>
            )}
          </div>
        </div>
      ) : (
        <div
          className={cn(
            'rounded-md text-sm',
            notes
              ? 'text-foreground leading-relaxed'
              : 'text-muted-foreground italic cursor-pointer hover:text-foreground transition-colors'
          )}
          onClick={() => !notes && setEditing(true)}
          role={!notes ? 'button' : undefined}
          tabIndex={!notes ? 0 : undefined}
          onKeyDown={(e) => {
            if (!notes && (e.key === 'Enter' || e.key === ' ')) {
              e.preventDefault()
              setEditing(true)
            }
          }}
        >
          {notes ?? `No ${label.toLowerCase()} — click to add`}
        </div>
      )}
    </div>
  )
}

'use client'

import { formatCurrency } from '@/lib/utils'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'
import { ShieldCheck, ShieldAlert } from 'lucide-react'

interface DepositStatusProps {
  depositCents: number
  depositPaid: boolean
  depositPaidAt: string | null
  className?: string
}

export function DepositStatus({
  depositCents,
  depositPaid,
  depositPaidAt,
  className,
}: DepositStatusProps) {
  if (depositCents === 0) return null

  return (
    <div className={cn('space-y-3', className)}>
      <div className="flex items-center gap-1.5">
        {depositPaid ? (
          <ShieldCheck className="h-3.5 w-3.5 text-emerald-500" />
        ) : (
          <ShieldAlert className="h-3.5 w-3.5 text-amber-500" />
        )}
        <span className="text-xs font-medium text-muted-foreground uppercase tracking-wider">
          Deposit
        </span>
      </div>

      <div className="flex items-center justify-between">
        <div className="space-y-0.5">
          <p className="text-sm font-medium tabular-nums">
            {formatCurrency(depositCents)}
          </p>
          {depositPaid && depositPaidAt && (
            <p className="text-xs text-muted-foreground">
              Paid{' '}
              {new Date(depositPaidAt).toLocaleDateString('en-US', {
                month: 'short',
                day: 'numeric',
                year: 'numeric',
              })}
            </p>
          )}
          {!depositPaid && (
            <p className="text-xs text-amber-600 dark:text-amber-400">Awaiting payment</p>
          )}
        </div>

        <span
          className={cn(
            'inline-flex items-center rounded-full px-2 py-0.5 text-xs font-medium',
            depositPaid
              ? 'bg-emerald-50 text-emerald-700 dark:bg-emerald-950/50 dark:text-emerald-400'
              : 'bg-amber-50 text-amber-700 dark:bg-amber-950/50 dark:text-amber-400'
          )}
        >
          {depositPaid ? 'Paid' : 'Unpaid'}
        </span>
      </div>

      {!depositPaid && (
        <Button
          variant="outline"
          size="sm"
          className="w-full h-8 text-xs"
          disabled
          data-testid="deposit-cta"
        >
          Collect deposit — available Sprint 4
        </Button>
      )}
    </div>
  )
}

'use client'

import { useMutation, useQueryClient } from '@tanstack/react-query'
import { Button } from '@/components/ui/button'
import { toast } from 'sonner'
import { logger } from '@/lib/logger'
import type { Database } from '@/lib/supabase/types'

type BookingStatus = Database['public']['Tables']['bookings']['Row']['status']

const ALLOWED_TRANSITIONS: Record<BookingStatus, BookingStatus[]> = {
  pending:     ['confirmed', 'cancelled'],
  confirmed:   ['in_progress', 'cancelled', 'no_show'],
  in_progress: ['completed', 'cancelled'],
  completed:   [],
  cancelled:   [],
  no_show:     [],
}

const TRANSITION_LABELS: Record<BookingStatus, string> = {
  confirmed:   'Confirm',
  in_progress: 'Start session',
  completed:   'Mark complete',
  cancelled:   'Cancel',
  no_show:     'No show',
  pending:     'Revert to pending',
}

const TRANSITION_VARIANT: Record<BookingStatus, 'default' | 'outline' | 'destructive'> = {
  confirmed:   'default',
  in_progress: 'default',
  completed:   'default',
  cancelled:   'destructive',
  no_show:     'outline',
  pending:     'outline',
}

interface StatusTransitionButtonsProps {
  bookingId: string
  currentStatus: BookingStatus
}

export function StatusTransitionButtons({
  bookingId,
  currentStatus,
}: StatusTransitionButtonsProps) {
  const queryClient = useQueryClient()
  const targets = ALLOWED_TRANSITIONS[currentStatus]

  const mutation = useMutation({
    mutationFn: async (newStatus: BookingStatus) => {
      const res = await fetch(`/api/bookings/${bookingId}/status`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: newStatus }),
      })
      if (!res.ok) {
        const err = await res.json() as { error?: string }
        throw new Error(err.error ?? 'Failed to update status')
      }
    },
    onSuccess: (_data, newStatus) => {
      void queryClient.invalidateQueries({ queryKey: ['booking', bookingId] })
      void queryClient.invalidateQueries({ queryKey: ['bookings'] })
      const label = TRANSITION_LABELS[newStatus]
      toast.success(`Status updated to ${newStatus.replace('_', ' ')}`)
      logger.info({ bookingId, newStatus, label }, 'booking status updated')
    },
    onError: (err: Error) => {
      toast.error(err.message)
      logger.error({ err, bookingId }, 'status transition failed')
    },
  })

  if (targets.length === 0) {
    return (
      <p className="text-xs text-muted-foreground">
        No further transitions available.
      </p>
    )
  }

  return (
    <div className="flex flex-wrap gap-2">
      {targets.map((target) => (
        <Button
          key={target}
          variant={TRANSITION_VARIANT[target]}
          size="sm"
          className="h-8 text-xs"
          disabled={mutation.isPending}
          onClick={() => mutation.mutate(target)}
        >
          {mutation.isPending && mutation.variables === target
            ? 'Updating...'
            : TRANSITION_LABELS[target]}
        </Button>
      ))}
    </div>
  )
}

