import { NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import { createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

const OfferSlotSchema = z.object({
  action: z.literal('offer'),
  booking_id: z.string().uuid(),
  /** How many hours the offer is valid — default 24 */
  offer_hours: z.number().int().min(1).max(168).default(24),
})

const CancelEntrySchema = z.object({
  action: z.literal('cancel'),
})

const PatchSchema = z.discriminatedUnion('action', [OfferSlotSchema, CancelEntrySchema])

interface Params {
  params: Promise<{ id: string }>
}

export async function PATCH(request: NextRequest, { params }: Params) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  const { id } = await params
  if (!z.string().uuid().safeParse(id).success) {
    return NextResponse.json({ error: 'Invalid waitlist entry ID' }, { status: 400 })
  }

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = PatchSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  try {
    const supabase = await createClient()

    // Verify entry belongs to this studio
    const { data: entry, error: fetchError } = await supabase
      .from('waitlist_entries')
      .select('id, status, client_id')
      .eq('id', id)
      .eq('studio_id', authUser.studioId)
      .single()

    if (fetchError || !entry) {
      return NextResponse.json({ error: 'Waitlist entry not found' }, { status: 404 })
    }

    if (parsed.data.action === 'offer') {
      if (entry.status !== 'active') {
        return NextResponse.json(
          { error: `Cannot offer slot — entry is already ${entry.status}` },
          { status: 409 }
        )
      }

      const expiresAt = new Date()
      expiresAt.setHours(expiresAt.getHours() + parsed.data.offer_hours)

      const { data: updated, error: updateError } = await supabase
        .from('waitlist_entries')
        .update({
          status: 'offered',
          offered_booking_id: parsed.data.booking_id,
          offered_at: new Date().toISOString(),
          offered_expires_at: expiresAt.toISOString(),
        })
        .eq('id', id)
        .eq('studio_id', authUser.studioId)
        .select('id, status, offered_at, offered_expires_at, offered_booking_id')
        .single()

      if (updateError) {
        logger.error({ err: updateError, entryId: id }, 'waitlist offer failed')
        return NextResponse.json({ error: 'Failed to offer slot' }, { status: 500 })
      }

      // Stub: email notification would be triggered here (Sprint 4)
      logger.info(
        { entryId: id, clientId: entry.client_id, bookingId: parsed.data.booking_id },
        'waitlist slot offered — email notification stub'
      )

      return NextResponse.json({ data: updated })
    }

    if (parsed.data.action === 'cancel') {
      const { data: updated, error: updateError } = await supabase
        .from('waitlist_entries')
        .update({ status: 'cancelled' })
        .eq('id', id)
        .eq('studio_id', authUser.studioId)
        .select('id, status')
        .single()

      if (updateError) {
        logger.error({ err: updateError, entryId: id }, 'waitlist cancel failed')
        return NextResponse.json({ error: 'Failed to cancel entry' }, { status: 500 })
      }

      return NextResponse.json({ data: updated })
    }

    return NextResponse.json({ error: 'Unknown action' }, { status: 400 })
  } catch (err) {
    logger.error({ err, entryId: id }, 'waitlist PATCH unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

export async function DELETE(_request: NextRequest, { params }: Params) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  const { id } = await params
  if (!z.string().uuid().safeParse(id).success) {
    return NextResponse.json({ error: 'Invalid waitlist entry ID' }, { status: 400 })
  }

  try {
    const supabase = await createClient()
    const { error } = await supabase
      .from('waitlist_entries')
      .update({ status: 'cancelled' })
      .eq('id', id)
      .eq('studio_id', authUser.studioId)

    if (error) {
      if (error.code === 'PGRST116') {
        return NextResponse.json({ error: 'Entry not found' }, { status: 404 })
      }
      logger.error({ err: error, entryId: id }, 'waitlist DELETE failed')
      return NextResponse.json({ error: 'Failed to remove entry' }, { status: 500 })
    }

    return new NextResponse(null, { status: 204 })
  } catch (err) {
    logger.error({ err, entryId: id }, 'waitlist DELETE unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

'use client'

import { useState, useCallback } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import { Button } from '@/components/ui/button'
import { Skeleton } from '@/components/ui/skeleton'
import { toast } from 'sonner'
import { logger } from '@/lib/logger'
import { formatDate } from '@/lib/utils'
import { Clock, ChevronLeft, ChevronRight, ListX, Send } from 'lucide-react'
import { cn } from '@/lib/utils'
import type { Database } from '@/lib/supabase/types'

type WaitlistStatus = Database['public']['Tables']['waitlist_entries']['Row']['status']

interface WaitlistEntry {
  id: string
  preferred_dates: string | null
  preferred_days_of_week: number[]
  notes: string | null
  status: WaitlistStatus
  offered_booking_id: string | null
  offered_at: string | null
  offered_expires_at: string | null
  created_at: string
  client: { id: string; first_name: string; last_name: string | null; email: string | null; phone: string | null } | null
  service: { id: string; name: string; duration_min: number; color: string | null } | null
  artist: { id: string; display_name: string; avatar_url: string | null } | null
}

interface WaitlistResponse {
  data: WaitlistEntry[]
  count: number
  page: number
  per_page: number
  total_pages: number
}

const DAY_LABELS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']
const PER_PAGE = 50

const STATUS_CLASSES: Record<WaitlistStatus, string> = {
  active: 'bg-blue-50 text-blue-700 dark:bg-blue-950/50 dark:text-blue-400',
  offered: 'bg-amber-50 text-amber-700 dark:bg-amber-950/50 dark:text-amber-400',
  booked: 'bg-emerald-50 text-emerald-700 dark:bg-emerald-950/50 dark:text-emerald-400',
  expired: 'bg-muted text-muted-foreground',
  cancelled: 'bg-muted text-muted-foreground',
}

interface WaitlistTableProps {
  onOfferSlot: (entry: WaitlistEntry) => void
}

export function WaitlistTable({ onOfferSlot }: WaitlistTableProps) {
  const queryClient = useQueryClient()
  const [page, setPage] = useState(1)
  const [statusFilter, setStatusFilter] = useState<WaitlistStatus | ''>('active')

  const { data, isLoading, error } = useQuery<WaitlistResponse>({
    queryKey: ['waitlist', 'table', statusFilter, page],
    queryFn: async () => {
      const params = new URLSearchParams({ per_page: String(PER_PAGE), page: String(page) })
      if (statusFilter) params.set('status', statusFilter)
      const res = await fetch(`/api/waitlist?${params.toString()}`)
      if (!res.ok) throw new Error('Failed to fetch waitlist')
      return res.json() as Promise<WaitlistResponse>
    },
  })

  const cancelMutation = useMutation({
    mutationFn: async (entryId: string) => {
      const res = await fetch(`/api/waitlist/${entryId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'cancel' }),
      })
      if (!res.ok) {
        const err = await res.json() as { error?: string }
        throw new Error(err.error ?? 'Failed to cancel entry')
      }
    },
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: ['waitlist'] })
      toast.success('Entry removed from waitlist')
    },
    onError: (err: Error) => {
      toast.error(err.message)
      logger.error({ err }, 'waitlist cancel failed')
    },
  })

  const entries = data?.data ?? []
  const totalPages = data?.total_pages ?? 1
  const totalCount = data?.count ?? 0

  const STATUS_OPTIONS: { value: WaitlistStatus | ''; label: string }[] = [
    { value: '', label: 'All statuses' },
    { value: 'active', label: 'Active' },
    { value: 'offered', label: 'Offered' },
    { value: 'booked', label: 'Booked' },
    { value: 'expired', label: 'Expired' },
    { value: 'cancelled', label: 'Cancelled' },
  ]

  const handleCancel = useCallback(
    (entryId: string) => {
      if (!window.confirm('Remove this entry from the waitlist?')) return
      cancelMutation.mutate(entryId)
    },
    [cancelMutation]
  )

  if (error) {
    return (
      <div className="p-6 text-center">
        <p className="text-sm text-destructive">Failed to load waitlist</p>
        <Button
          variant="outline"
          size="sm"
          className="mt-3"
          onClick={() => void queryClient.invalidateQueries({ queryKey: ['waitlist', 'table'] })}
        >
          Retry
        </Button>
      </div>
    )
  }

  return (
    <div className="flex flex-col flex-1 overflow-hidden">
      {/* Toolbar */}
      <div className="flex flex-wrap items-center gap-2 px-6 py-3 border-b border-border/40">
        <select
          value={statusFilter}
          onChange={(e) => {
            setStatusFilter(e.target.value as WaitlistStatus | '')
            setPage(1)
          }}
          className="h-8 rounded-md border border-input bg-background px-2 text-xs text-foreground"
        >
          {STATUS_OPTIONS.map((o) => (
            <option key={o.value} value={o.value}>{o.label}</option>
          ))}
        </select>

        <p className="ml-auto text-xs text-muted-foreground tabular-nums">
          {totalCount} {totalCount === 1 ? 'entry' : 'entries'}
        </p>
      </div>

      {/* Table */}
      <div className="flex-1 overflow-auto">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Client</TableHead>
              <TableHead>Service</TableHead>
              <TableHead>Artist</TableHead>
              <TableHead>Preferred days</TableHead>
              <TableHead>Added</TableHead>
              <TableHead>Status</TableHead>
              <TableHead className="w-24" />
            </TableRow>
          </TableHeader>
          <TableBody>
            {isLoading &&
              Array.from({ length: 8 }).map((_, i) => (
                <TableRow key={i}>
                  <TableCell><Skeleton className="h-4 w-28" /></TableCell>
                  <TableCell><Skeleton className="h-4 w-20" /></TableCell>
                  <TableCell><Skeleton className="h-4 w-20" /></TableCell>
                  <TableCell><Skeleton className="h-4 w-24" /></TableCell>
                  <TableCell><Skeleton className="h-4 w-16" /></TableCell>
                  <TableCell><Skeleton className="h-5 w-14 rounded-full" /></TableCell>
                  <TableCell><Skeleton className="h-7 w-16" /></TableCell>
                </TableRow>
              ))}

            {!isLoading && entries.length === 0 && (
              <TableRow>
                <TableCell colSpan={7} className="py-16 text-center">
                  <div className="flex flex-col items-center gap-3">
                    <div className="rounded-xl bg-muted/50 p-3">
                      <Clock className="h-8 w-8 text-muted-foreground/50" />
                    </div>
                    <div className="space-y-1">
                      <p className="text-sm font-medium">
                        {statusFilter ? 'No entries with this status' : 'Waitlist is empty'}
                      </p>
                      <p className="text-xs text-muted-foreground">
                        {statusFilter
                          ? 'Try switching to "All statuses"'
                          : 'Add clients to the waitlist when your calendar is full'}
                      </p>
                    </div>
                  </div>
                </TableCell>
              </TableRow>
            )}

            {!isLoading &&
              entries.map((entry) => (
                <TableRow key={entry.id}>
                  <TableCell>
                    {entry.client ? (
                      <div>
                        <p className="text-sm font-medium">
                          {entry.client.first_name} {entry.client.last_name ?? ''}
                        </p>
                        {entry.client.email && (
                          <p className="text-xs text-muted-foreground truncate max-w-[160px]">
                            {entry.client.email}
                          </p>
                        )}
                      </div>
                    ) : (
                      <span className="text-xs text-muted-foreground">—</span>
                    )}
                  </TableCell>

                  <TableCell>
                    {entry.service ? (
                      <div className="flex items-center gap-1.5">
                        {entry.service.color && (
                          <span
                            className="h-2 w-2 rounded-full shrink-0"
                            style={{ backgroundColor: entry.service.color }}
                          />
                        )}
                        <span className="text-sm truncate max-w-[120px]">{entry.service.name}</span>
                      </div>
                    ) : (
                      <span className="text-xs text-muted-foreground">Any</span>
                    )}
                  </TableCell>

                  <TableCell>
                    <span className="text-sm">
                      {entry.artist?.display_name ?? <span className="text-muted-foreground text-xs">Any</span>}
                    </span>
                  </TableCell>

                  <TableCell>
                    {entry.preferred_days_of_week.length > 0 ? (
                      <div className="flex gap-0.5">
                        {entry.preferred_days_of_week.map((d) => (
                          <span
                            key={d}
                            className="inline-flex items-center rounded bg-muted px-1 py-0.5 text-xs font-medium"
                          >
                            {DAY_LABELS[d]}
                          </span>
                        ))}
                      </div>
                    ) : (
                      <span className="text-xs text-muted-foreground">Flexible</span>
                    )}
                  </TableCell>

                  <TableCell className="text-xs text-muted-foreground tabular-nums">
                    {formatDate(entry.created_at, { month: 'short', day: 'numeric' })}
                  </TableCell>

                  <TableCell>
                    <span
                      className={cn(
                        'inline-flex items-center rounded-full px-2 py-0.5 text-xs font-medium capitalize',
                        STATUS_CLASSES[entry.status]
                      )}
                    >
                      {entry.status}
                    </span>
                    {entry.offered_expires_at && entry.status === 'offered' && (
                      <p className="text-xs text-muted-foreground mt-0.5 tabular-nums">
                        Expires{' '}
                        {new Date(entry.offered_expires_at).toLocaleDateString('en-US', {
                          month: 'short',
                          day: 'numeric',
                        })}
                      </p>
                    )}
                  </TableCell>

                  <TableCell>
                    <div className="flex items-center gap-1">
                      {entry.status === 'active' && (
                        <Button
                          variant="outline"
                          size="sm"
                          className="h-7 text-xs gap-1"
                          onClick={() => onOfferSlot(entry)}
                        >
                          <Send className="h-3 w-3" />
                          Offer
                        </Button>
                      )}
                      {(entry.status === 'active' || entry.status === 'offered') && (
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-7 w-7 text-muted-foreground hover:text-destructive"
                          disabled={cancelMutation.isPending}
                          onClick={() => handleCancel(entry.id)}
                          aria-label="Remove from waitlist"
                        >
                          <ListX className="h-3.5 w-3.5" />
                        </Button>
                      )}
                    </div>
                  </TableCell>
                </TableRow>
              ))}
          </TableBody>
        </Table>
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex items-center justify-between border-t border-border/40 px-6 py-3">
          <p className="text-xs text-muted-foreground tabular-nums">
            {(page - 1) * PER_PAGE + 1}–{Math.min(page * PER_PAGE, totalCount)} of {totalCount}
          </p>
          <div className="flex items-center gap-1">
            <Button
              variant="ghost"
              size="icon"
              className="h-7 w-7"
              disabled={page === 1}
              onClick={() => setPage((p) => p - 1)}
              aria-label="Previous page"
            >
              <ChevronLeft className="h-4 w-4" />
            </Button>
            <span className="text-xs tabular-nums px-2">{page} / {totalPages}</span>
            <Button
              variant="ghost"
              size="icon"
              className="h-7 w-7"
              disabled={page === totalPages}
              onClick={() => setPage((p) => p + 1)}
              aria-label="Next page"
            >
              <ChevronRight className="h-4 w-4" />
            </Button>
          </div>
        </div>
      )}
    </div>
  )
}

'use client'

import { useState } from 'react'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { Button } from '@/components/ui/button'
import { Label } from '@/components/ui/label'
import { Textarea } from '@/components/ui/textarea'
import { ClientFinder } from '@/components/booking/ClientFinder'
import { toast } from 'sonner'
import { logger } from '@/lib/logger'
import { cn } from '@/lib/utils'

const DAY_OPTIONS = [
  { value: 1, label: 'Mon' },
  { value: 2, label: 'Tue' },
  { value: 3, label: 'Wed' },
  { value: 4, label: 'Thu' },
  { value: 5, label: 'Fri' },
  { value: 6, label: 'Sat' },
  { value: 0, label: 'Sun' },
]

interface Service {
  id: string
  name: string
  color: string | null
}

interface Artist {
  id: string
  display_name: string
}

interface AddToWaitlistFormProps {
  onSuccess: () => void
  onCancel: () => void
}

export function AddToWaitlistForm({ onSuccess, onCancel }: AddToWaitlistFormProps) {
  const queryClient = useQueryClient()

  const [selectedClientId, setSelectedClientId] = useState<string | null>(null)
  const [newClientData, setNewClientData] = useState<{
    first_name: string; last_name: string; email: string; phone: string
  } | null>(null)
  const [selectedServiceId, setSelectedServiceId] = useState<string>('')
  const [selectedArtistId, setSelectedArtistId] = useState<string>('')
  const [selectedDays, setSelectedDays] = useState<number[]>([])
  const [notes, setNotes] = useState('')

  const { data: servicesData } = useQuery<{ data: Service[] }>({
    queryKey: ['services'],
    queryFn: async () => {
      const res = await fetch('/api/services')
      if (!res.ok) throw new Error('Failed to fetch services')
      return res.json() as Promise<{ data: Service[] }>
    },
  })

  const { data: artistsData } = useQuery<{ data: Artist[] }>({
    queryKey: ['artists', 'active'],
    queryFn: async () => {
      const res = await fetch('/api/artists?status=active')
      if (!res.ok) throw new Error('Failed to fetch artists')
      return res.json() as Promise<{ data: Artist[] }>
    },
  })

  const mutation = useMutation({
    mutationFn: async () => {
      let clientId = selectedClientId

      // Create client inline if needed
      if (!clientId && newClientData) {
        const res = await fetch('/api/clients', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(newClientData),
        })
        if (!res.ok) {
          const err = await res.json() as { error?: string }
          throw new Error(err.error ?? 'Failed to create client')
        }
        const { data } = await res.json() as { data: { id: string } }
        clientId = data.id
      }

      if (!clientId) throw new Error('Please select or add a client')

      const res = await fetch('/api/waitlist', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          client_id: clientId,
          service_id: selectedServiceId || undefined,
          artist_id: selectedArtistId || undefined,
          preferred_days_of_week: selectedDays,
          notes: notes || undefined,
        }),
      })

      if (!res.ok) {
        const err = await res.json() as { error?: string }
        throw new Error(err.error ?? 'Failed to add to waitlist')
      }
    },
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: ['waitlist'] })
      toast.success('Added to waitlist')
      onSuccess()
    },
    onError: (err: Error) => {
      toast.error(err.message)
      logger.error({ err }, 'add to waitlist failed')
    },
  })

  const toggleDay = (day: number) => {
    setSelectedDays((prev) =>
      prev.includes(day) ? prev.filter((d) => d !== day) : [...prev, day]
    )
  }

  const canSubmit = selectedClientId !== null || newClientData !== null

  return (
    <div className="space-y-5">
      {/* Client */}
      <div className="space-y-2">
        <Label className="text-xs font-medium">Client *</Label>
        <ClientFinder
          selectedClientId={selectedClientId}
          onSelectClient={(id) => { setSelectedClientId(id); setNewClientData(null) }}
          onNewClient={(data) => { setNewClientData(data); setSelectedClientId(null) }}
        />
      </div>

      {/* Service */}
      <div className="space-y-1.5">
        <Label htmlFor="wl-service" className="text-xs font-medium">
          Service <span className="text-muted-foreground font-normal">(optional)</span>
        </Label>
        <select
          id="wl-service"
          value={selectedServiceId}
          onChange={(e) => setSelectedServiceId(e.target.value)}
          className="w-full h-9 rounded-md border border-input bg-background px-2 text-sm text-foreground"
        >
          <option value="">Any service</option>
          {(servicesData?.data ?? []).map((s) => (
            <option key={s.id} value={s.id}>{s.name}</option>
          ))}
        </select>
      </div>

      {/* Artist */}
      <div className="space-y-1.5">
        <Label htmlFor="wl-artist" className="text-xs font-medium">
          Artist <span className="text-muted-foreground font-normal">(optional)</span>
        </Label>
        <select
          id="wl-artist"
          value={selectedArtistId}
          onChange={(e) => setSelectedArtistId(e.target.value)}
          className="w-full h-9 rounded-md border border-input bg-background px-2 text-sm text-foreground"
        >
          <option value="">Any artist</option>
          {(artistsData?.data ?? []).map((a) => (
            <option key={a.id} value={a.id}>{a.display_name}</option>
          ))}
        </select>
      </div>

      {/* Preferred days */}
      <div className="space-y-2">
        <Label className="text-xs font-medium">
          Preferred days <span className="text-muted-foreground font-normal">(optional)</span>
        </Label>
        <div className="flex flex-wrap gap-1.5">
          {DAY_OPTIONS.map((day) => (
            <button
              key={day.value}
              type="button"
              onClick={() => toggleDay(day.value)}
              className={cn(
                'rounded-md px-2.5 py-1 text-xs font-medium transition-colors border',
                selectedDays.includes(day.value)
                  ? 'bg-primary text-primary-foreground border-primary'
                  : 'bg-background text-muted-foreground border-border hover:bg-muted'
              )}
            >
              {day.label}
            </button>
          ))}
        </div>
      </div>

      {/* Notes */}
      <div className="space-y-1.5">
        <Label htmlFor="wl-notes" className="text-xs font-medium">
          Notes <span className="text-muted-foreground font-normal">(optional)</span>
        </Label>
        <Textarea
          id="wl-notes"
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
          placeholder="Client preferences, urgency, special requirements..."
          className="text-sm min-h-[80px] resize-none"
          maxLength={1000}
        />
      </div>

      {/* Actions */}
      <div className="flex items-center gap-2 pt-1">
        <Button
          size="sm"
          disabled={!canSubmit || mutation.isPending}
          onClick={() => mutation.mutate()}
        >
          {mutation.isPending ? 'Adding...' : 'Add to waitlist'}
        </Button>
        <Button variant="outline" size="sm" onClick={onCancel} disabled={mutation.isPending}>
          Cancel
        </Button>
      </div>
    </div>
  )
}

'use client'

import { useState } from 'react'
import { useMutation, useQueryClient } from '@tanstack/react-query'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Label } from '@/components/ui/label'
import { toast } from 'sonner'
import { logger } from '@/lib/logger'

interface OfferSlotDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  entryId: string | null
  clientName: string
  onSuccess: () => void
}

export function OfferSlotDialog({
  open,
  onOpenChange,
  entryId,
  clientName,
  onSuccess,
}: OfferSlotDialogProps) {
  const queryClient = useQueryClient()
  const [bookingId, setBookingId] = useState('')
  const [offerHours, setOfferHours] = useState(24)

  const mutation = useMutation({
    mutationFn: async () => {
      if (!entryId) throw new Error('No entry selected')
      if (!bookingId.trim()) throw new Error('Booking ID is required')

      const res = await fetch(`/api/waitlist/${entryId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'offer',
          booking_id: bookingId.trim(),
          offer_hours: offerHours,
        }),
      })

      if (!res.ok) {
        const err = await res.json() as { error?: string }
        throw new Error(err.error ?? 'Failed to offer slot')
      }
    },
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: ['waitlist'] })
      toast.success(`Slot offered to ${clientName}`)
      logger.info({ entryId, bookingId }, 'waitlist slot offered')
      setBookingId('')
      setOfferHours(24)
      onOpenChange(false)
      onSuccess()
    },
    onError: (err: Error) => {
      toast.error(err.message)
      logger.error({ err, entryId }, 'offer slot failed')
    },
  })

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Offer a slot</DialogTitle>
          <DialogDescription>
            Link a pending booking to {clientName} and notify them of the available time.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-2">
          <div className="space-y-1.5">
            <Label htmlFor="offer-booking-id" className="text-sm">
              Booking ID
            </Label>
            <input
              id="offer-booking-id"
              type="text"
              value={bookingId}
              onChange={(e) => setBookingId(e.target.value)}
              placeholder="Paste a booking UUID..."
              className="w-full h-9 rounded-md border border-input bg-background px-3 text-sm text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-1 focus:ring-ring"
            />
            <p className="text-xs text-muted-foreground">
              The pending booking you want to offer to this waitlist client.
            </p>
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="offer-hours" className="text-sm">
              Offer expires in
            </Label>
            <select
              id="offer-hours"
              value={offerHours}
              onChange={(e) => setOfferHours(Number(e.target.value))}
              className="w-full h-9 rounded-md border border-input bg-background px-2 text-sm text-foreground"
            >
              <option value={12}>12 hours</option>
              <option value={24}>24 hours</option>
              <option value={48}>48 hours</option>
              <option value={72}>72 hours</option>
            </select>
          </div>

          <div className="rounded-md bg-muted/50 border border-border/60 px-3 py-2 text-xs text-muted-foreground">
            Email notification stub — will be wired in Sprint 4.
          </div>
        </div>

        <DialogFooter>
          <Button
            variant="outline"
            onClick={() => onOpenChange(false)}
            disabled={mutation.isPending}
          >
            Cancel
          </Button>
          <Button
            onClick={() => mutation.mutate()}
            disabled={mutation.isPending || !bookingId.trim()}
          >
            {mutation.isPending ? 'Offering...' : 'Offer slot'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}
